32	  bool migrate() {
33	    if (!_xcodeProjectInfoFile.existsSync()) {
34	      logger.printTrace('Xcode project not found, skipping framework link and embedding migration');
35	      return true;
36	    }
37	
38	    processFileLines(_xcodeProjectInfoFile);
39	
40	    return true;
41	  }
